<?php
declare(strict_types=1);
namespace StageArtCore\Presentation\Admin;
use StageArtCore\Domain\Survey\SurveyRepository;
use StageArtCore\Domain\Member\MemberRepository;
final class SurveyAdmin{private SurveyRepository $repo;private MemberRepository $members;public function __construct(){$this->repo=new SurveyRepository();$this->members=new MemberRepository();add_action('admin_post_stageart_save_survey',[$this,'save']);}public function register():void{add_submenu_page('stageart-plugin','アンケート','アンケート','manage_options','stageart-surveys',[$this,'render']);}public function render():void{if(!current_user_can('manage_options'))wp_die('権限がありません。');$pid=(int)($_GET['production_id']??0);$p=$pid?get_post($pid):null;if(!$pid){$this->listProductions();return;}if(!$p||$p->post_type!=='stageart_production'){echo'<div class="wrap"><h1>アンケート</h1><p>対象の公演が指定されていません。</p><p><a class="button" href="'.esc_url(admin_url('admin.php?page=stageart-surveys')).'">公演一覧に戻る</a></p></div>';return;}$s=$this->repo->findByProduction($pid);$qs=$s?$this->repo->questions((int)$s['id']):[];$url=home_url('/production/'.($p->post_name?:$pid).'/questionnaire/');if(isset($_GET['preview'])){$this->preview($p,$s,$qs,$url);return;}echo'<div class="wrap"><h1>公演アンケート</h1><p><strong>公演：</strong>'.esc_html($p->post_title).'</p><p><a class="button" href="'.esc_url($url).'" target="_blank">公開アンケートを開く</a> <a class="button" href="'.esc_url(admin_url('admin.php?page=stageart-surveys&production_id='.$pid.'&preview=1')).'" target="_blank">アンケートをプレビュー</a> <a class="button" href="'.esc_url(admin_url('admin.php?page=stageart-survey-qr&production_id='.$pid)).'">QRコードを印刷</a></p>';if($s)echo'<p><a class="button" href="'.esc_url(admin_url('admin.php?page=stageart-survey-results&survey_id='.(int)$s['id'])).'">アンケート結果を見る</a></p>';echo'<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('stageart_survey_action');echo'<input type="hidden" name="action" value="stageart_save_survey"><input type="hidden" name="production_id" value="'.$pid.'"><table class="form-table"><tr><th>タイトル</th><td><input class="regular-text" name="title" value="'.esc_attr($s['title']??'アンケート').'"></td></tr><tr><th>説明</th><td><textarea class="large-text" rows="4" name="description">'.esc_textarea($s['description']??'').'</textarea></td></tr><tr><th>公開URL</th><td><code>'.esc_html($url).'</code></td></tr><tr><th>公開状態</th><td><select name="status"><option value="publish" '.selected($s['status']??'publish','publish',false).'>公開</option><option value="draft" '.selected($s['status']??'publish','draft',false).'>下書き</option></select></td></tr><tr><th>回答者情報</th><td><label><input type="checkbox" name="collect_name" value="1" '.checked(!empty($s['collect_name']),true,false).'> お名前（任意）</label><br><label><input type="checkbox" name="collect_email" value="1" '.checked(!empty($s['collect_email']),true,false).'> メールアドレス（任意）</label><p class="description">回答フォームで入力欄を表示します。未入力でも回答できます。</p></td></tr></table><h2>設問</h2><table class="widefat" id="sa-survey-questions"><thead><tr><th>形式</th><th>質問</th><th>説明</th><th>必須</th><th>選択肢</th><th></th></tr></thead><tbody>';foreach($qs as$i=>$q)$this->row($i,$q);echo'</tbody></table><p><button type="button" class="button" id="sa-add-survey-question">＋ 設問を追加</button></p><p><button class="button button-primary" type="submit">保存</button></p></form></div>';$this->script();}private function listProductions():void{$posts=get_posts(['post_type'=>'stageart_production','post_status'=>['publish','draft','private'],'numberposts'=>-1,'orderby'=>'date','order'=>'DESC']);echo'<div class="wrap"><h1>アンケート</h1><p>公演ごとにアンケートを設定・回答結果を確認できます。公演を登録するとアンケートが自動作成されます。</p><table class="widefat striped"><thead><tr><th>公演名</th><th>公演状態</th><th>アンケート</th><th>回答数</th><th>公開URL</th><th>操作</th></tr></thead><tbody>';if(!$posts){echo'<tr><td colspan="6">公演はまだ登録されていません。</td></tr>';}foreach($posts as$p){$id=(int)$p->ID;$sid=$this->repo->ensureForProduction($id);$s=$this->repo->findByProduction($id);$count=$this->repo->responseCount($sid);$url=home_url('/production/'.($p->post_name?:$id).'/questionnaire/');$edit=admin_url('admin.php?page=stageart-surveys&production_id='.$id);$results=admin_url('admin.php?page=stageart-survey-results&survey_id='.$sid);echo'<tr><td><strong>'.esc_html($p->post_title).'</strong></td><td>'.esc_html($p->post_status==='publish'?'公開':'下書き').'</td><td>'.esc_html($s['status']==='publish'?'公開':'下書き').'</td><td>'.(int)$count.'</td><td><code>'.esc_html($url).'</code></td><td><a class="button" href="'.esc_url($edit).'">設定</a> <a class="button" href="'.esc_url($results).'">回答結果</a></td></tr>';}echo'</tbody></table></div>';}
private function preview(\WP_Post$p,?array$s,array$qs,string$url):void{echo'<!doctype html><html><head><meta charset="utf-8"><title>アンケートプレビュー</title><style>body{font-family:-apple-system,BlinkMacSystemFont,"Yu Gothic",Meiryo,sans-serif;max-width:760px;margin:40px auto;padding:0 20px;line-height:1.8}fieldset{border:1px solid #ddd;margin:18px 0;padding:18px}legend{font-weight:700}input,textarea,select{max-width:100%;padding:7px} .notice{padding:12px;background:#fff8e5;border:1px solid #e5c66b}</style></head><body><div class="notice">これは管理画面のプレビューです。回答は送信されません。</div><p>'.esc_html($p->post_title).'</p><h1>'.esc_html($s['title']??'アンケート').'</h1>';if(!empty($s['description']))echo'<div>'.wp_kses_post($s['description']).'</div>';foreach($qs as$q){echo'<fieldset><legend>'.esc_html($q['label']).(!empty($q['is_required'])?' *':'').'</legend>';if(!empty($q['description']))echo'<p>'.esc_html($q['description']).'</p>';switch($q['type']){case'radio':foreach((array)$q['options']as$o)echo'<label><input type="radio" disabled> '.esc_html($o).'</label><br>';break;case'checkbox':foreach((array)$q['options']as$o)echo'<label><input type="checkbox" disabled> '.esc_html($o).'</label><br>';break;case'select':echo'<select disabled><option>選択してください</option>';foreach((array)$q['options']as$o)echo'<option>'.esc_html($o).'</option>';echo'</select>';break;case'rating':echo'<select disabled><option>評価を選択</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select>';break;case'textarea':echo'<textarea rows="5" disabled></textarea>';break;default:echo'<input type="text" disabled>';}$this->previewClose();}echo'<p><code>'.esc_html($url).'</code></p></body></html>';exit;}private function previewClose():void{echo'</fieldset>';}
private function row(int$i,array$q):void{$o=(array)($q["options"]??[]);$selected=array_map("intval",$o);$memberType=in_array($q["type"]??"",["member_radio","member_checkbox"],true);$members=$this->members->all(false);$memberOptions="";foreach($members as$m){$mid=(int)$m["id"];$full=$this->members->find($mid);$roles=[];foreach((array)($full["roles"]??[])as$r){$roles[]=MemberRepository::ROLES[$r]??$r;}$label=(string)$m["name"].($roles?"（".implode("・",$roles)."）":"");$memberOptions.="<label><input type=\"checkbox\" name=\"questions[".$i."][member_ids][]\" value=\"".$mid."\" ".checked(in_array($mid,$selected,true),true,false)."> ".esc_html($label)."</label><br>";}echo '<tr data-index="'.$i.'"><td><input type="hidden" name="questions['.$i.'][id]" value="'.(int)($q["id"]??0).'"><select name="questions['.$i.'][type]" class="sa-survey-type"><option value="text" '.selected($q["type"]??"","text",false).'>短文</option><option value="textarea" '.selected($q["type"]??"","textarea",false).'>長文</option><option value="radio" '.selected($q["type"]??"","radio",false).'>ラジオ</option><option value="checkbox" '.selected($q["type"]??"","checkbox",false).'>複数選択</option><option value="member_radio" '.selected($q["type"]??"","member_radio",false).'>メンバー（1人）</option><option value="member_checkbox" '.selected($q["type"]??"","member_checkbox",false).'>メンバー（複数）</option><option value="select" '.selected($q["type"]??"","select",false).'>プルダウン</option><option value="rating" '.selected($q["type"]??"","rating",false).'>5段階評価</option></select></td>'<td><input class="regular-text" name="questions['.$i.'][label]" value="'.esc_attr($q["label"]??"").'" required></td><td><input class="regular-text" name="questions['.$i.'][description]" value="'.esc_attr($q["description"]??"").'"></td><td><input type="checkbox" name="questions['.$i.'][is_required]" value="1" '.checked(!empty($q["is_required"]),true,false).'></td><td><div class="sa-member-options" style="'.($memberType?"":"display:none").'"><strong>対象メンバー</strong><p class="description">名前（役割）で表示されます。1人選択・複数選択は公開フォーム側で自動的に切り替わります。</p>'.$memberOptions.'</div><div class="sa-text-options" style="'.($memberType?"display:none":"").'"><textarea name="questions['.$i.'][options]" rows="3" placeholder="1行1選択肢">'.esc_textarea(implode("\n",array_map("strval",$o))).'</textarea></div></td><td><button type="button" class="button-link-delete sa-survey-remove">削除</button></td></tr>';}public function save():void{if(!current_user_can('manage_options'))wp_die('権限がありません。');check_admin_referer('stageart_survey_action');$pid=(int)($_POST['production_id']??0);$qs=[];foreach((array)($_POST['questions']??[]) as$q){if(!is_array($q))continue;$qs[]=['id'=>(int)($q['id']??0),'type'=>sanitize_key((string)($q['type']??'textarea')),'label'=>(string)($q['label']??''),'description'=>(string)($q['description']??''),'is_required'=>!empty($q['is_required']),'options'=>in_array(sanitize_key((string)($q['type']??'')),['member_radio','member_checkbox'],true)?array_values(array_filter(array_map('intval',(array)($q['member_ids']??[])))):(preg_split('/\r\n|\r|\n/',(string)($q['options']??''))?:[])];}$this->repo->save($pid,['title'=>(string)($_POST['title']??'アンケート'),'description'=>(string)($_POST['description']??''),'slug'=>'questionnaire','status'=>sanitize_key((string)($_POST['status']??'publish')),'collect_name'=>!empty($_POST['collect_name']),'collect_email'=>!empty($_POST['collect_email'])],$qs);wp_safe_redirect(admin_url('admin.php?page=stageart-surveys&production_id='.$pid.'&saved=1'));exit;}private function script():void{$members=$this->members->all(false);$memberOptions="";foreach($members as$m){$mid=(int)$m["id"];$full=$this->members->find($mid);$roles=[];foreach((array)($full["roles"]??[])as$r)$roles[]=MemberRepository::ROLES[$r]??$r;$label=(string)$m["name"].($roles?"（".implode("・",$roles)."）":"");$memberOptions.="<label><input type=\"checkbox\" data-member-checkbox value=\"".$mid."\"> ".esc_html($label)."</label><br>";}$memberOptions=wp_json_encode($memberOptions,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);echo "<script>(function(){const t=document.querySelector('#sa-survey-questions tbody'),a=document.querySelector('#sa-add-survey-question'),memberOptions=".$memberOptions.";if(!t||!a)return;function bind(row){const type=row.querySelector('.sa-survey-type'),m=row.querySelector('.sa-member-options'),x=row.querySelector('.sa-text-options');if(!type)return;const sync=()=>{const isMember=type.value==='member_radio'||type.value==='member_checkbox';if(m)m.style.display=isMember?'':'none';if(x)x.style.display=isMember?'none':'';};type.addEventListener('change',sync);sync();}t.querySelectorAll('tr').forEach(bind);a.onclick=()=>{const i=t.children.length,row=document.createElement('tr');row.dataset.index=i;row.innerHTML='<td><input type=\"hidden\" name=\"questions['+i+'][id]\" value=\"0\"><select name=\"questions['+i+'][type]\" class=\"sa-survey-type\"><option value=\"text\">短文</option><option value=\"textarea\" selected>長文</option><option value=\"radio\">ラジオ</option><option value=\"checkbox\">複数選択</option><option value=\"member_radio\">メンバー（1人）</option><option value=\"member_checkbox\">メンバー（複数）</option><option value=\"select\">プルダウン</option><option value=\"rating\">5段階評価</option></select></td><td><input class=\"regular-text\" name=\"questions['+i+'][label]\" required></td><td><input class=\"regular-text\" name=\"questions['+i+'][description]\"></td><td><input type=\"checkbox\" name=\"questions['+i+'][is_required]\" value=\"1\"></td><td><div class=\"sa-member-options\" style=\"display:none\"><strong>対象メンバー</strong><p class=\"description\">名前（役割）で表示されます。</p>'+memberOptions.replaceAll('__INDEX__',String(i))+'</div><div class=\"sa-text-options\"><textarea name=\"questions['+i+'][options]\" rows=\"3\" placeholder=\"1行1選択肢\"></textarea></div></td><td><button type=\"button\" class=\"button-link-delete sa-survey-remove\">削除</button></td>';t.appendChild(row);bind(row)};t.addEventListener('click',e=>{if(e.target.classList.contains('sa-survey-remove'))e.target.closest('tr').remove()})})();</script>";}